import re

def forth(src: str) -> list[int]:
    tokens = src.lower().split()
    defs = {}
    builtins = {
        '+': lambda s: s.append(s.pop() + s.pop()),
        '-': lambda s: s.append(s.pop(-2) - s.pop()),
        '*': lambda s: s.append(s.pop() * s.pop()),
        '/': lambda s: s.append(s.pop(-2) // s.pop()),
        'mod': lambda s: s.append(s.pop(-2) % s.pop()),
        '/mod': lambda s: (s.append(s.pop(-2) % s.pop()), s.append(s.pop(-2) // s.pop())),
        'negate': lambda s: s.append(-s.pop()),
        'abs': lambda s: s.append(abs(s.pop())),
        'dup': lambda s: (a := s.pop(), s.append(a), s.append(a)),
        'drop': lambda s: s.pop(),
        'swap': lambda s: (a := s.pop(), b := s.pop(), s.append(a), s.append(b)),
        'over': lambda s: (a := s.pop(), b := s.pop(), s.append(b), s.append(a), s.append(b)),
        'rot': lambda s: (a := s.pop(), b := s.pop(), c := s.pop(), s.append(b), s.append(a), s.append(c)),
        '=': lambda s: s.append(-1 if s.pop() == s.pop() else 0),
        '<': lambda s: s.append(-1 if s.pop() < s.pop() else 0),
        '>': lambda s: s.append(-1 if s.pop() > s.pop() else 0),
    }

    control_words = {'if', 'else', 'then', 'begin', 'until'}
    num_pat = re.compile(r'^-?\d+$')

    def resolve_word(word):
        if word in defs:
            return ('call', defs[word])
        if word in builtins:
            return ('call', builtins[word])
        if num_pat.match(word):
            return ('lit', int(word))
        raise ValueError(f"Unknown word: {word}")

    def execute(instrs, stack):
        for instr in instrs:
            kind = instr[0]
            if kind == 'lit':
                stack.append(instr[1])
            elif kind == 'call':
                instr[1](stack)
            elif kind == 'if':
                then_b, else_b = instr[1], instr[2]
                flag = stack.pop()
                if flag != 0:
                    execute(then_b, stack)
                else:
                    execute(else_b, stack)
            elif kind == 'begin':
                body = instr[1]
                while True:
                    execute(body, stack)
                    flag = stack.pop()
                    if flag != 0:
                        break

    i = 0
    n = len(tokens)
    top_level = []

    while i < n:
        tok = tokens[i]
        if tok == ':':
            i += 1
            if i >= n:
                raise ValueError("':' with no name")
            name = tokens[i]
            i += 1
            if num_pat.match(name):
                raise ValueError("Name cannot be a number literal")

            ctx_stack = [{'type': 'root', 'items': []}]
            while i < n:
                tok = tokens[i]
                if tok == ';':
                    i += 1
                    break
                if tok == ':':
                    raise ValueError("':' inside body")
                if tok == 'if':
                    ctx_stack.append({'type': 'if', 'then': [], 'else': None})
                elif tok == 'else':
                    ctx = ctx_stack[-1]
                    if ctx['type'] != 'if':
                        raise ValueError("Misplaced 'else'")
                    ctx['type'] = 'if_else'
                    ctx['else'] = []
                elif tok == 'then':
                    ctx = ctx_stack.pop()
                    if ctx['type'] not in ('if', 'if_else'):
                        raise ValueError("Misplaced 'then'")
                    parent = ctx_stack[-1]
                    parent['items'].append(('if', ctx['then'], ctx['else'] if ctx['type'] == 'if_else' else []))
                elif tok == 'begin':
                    ctx_stack.append({'type': 'begin', 'body': []})
                elif tok == 'until':
                    ctx = ctx_stack.pop()
                    if ctx['type'] != 'begin':
                        raise ValueError("Misplaced 'until'")
                    parent = ctx_stack[-1]
                    parent['items'].append(('begin', ctx['body']))
                else:
                    resolved = resolve_word(tok)
                    ctx_stack[-1]['items'].append(resolved)
                i += 1

            if i >= n:
                raise ValueError("Missing ';'")
            if len(ctx_stack) > 1 or ctx_stack[0]['type'] != 'root':
                raise ValueError("Unbalanced control words")
            top_level.append(('def', name, ctx_stack[0]['items']))

        elif tok in control_words:
            raise ValueError("Control word outside body")
        elif tok == ';':
            raise ValueError("';' outside body")
        else:
            resolved = resolve_word(tok)
            top_level.append(('run', resolved))
            i += 1

    stack = []
    for item in top_level:
        if item[0] == 'def':
            defs[item[1]] = item[2]
        else:
            execute([item[1]], stack)

    return stack

