def mod_sqrts(a: int, m: int) -> list[int]:
    if m < 1:
        raise ValueError("Modulus m must be >= 1")
    if m == 1:
        return [0]

    a = a % m

    # Factorize m into prime powers
    factors = []
    d = 2
    temp = m
    while d * d <= temp:
        if temp % d == 0:
            e = 0
            while temp % d == 0:
                e += 1
                temp //= d
            factors.append((d, e))
        d += 1
    if temp > 1:
        factors.append((temp, 1))

    # Solve for each prime power and combine using CRT
    all_roots = [(0, 1)]
    current_mod = 1

    for p, e in factors:
        p_pow = p ** e
        roots_p = _solve_prime_power(a, p, e)
        if not roots_p:
            return []

        new_roots = []
        inv = pow(current_mod, -1, p_pow)

        for rem1, mod1 in all_roots:
            for r2 in roots_p:
                k = ((r2 - rem1) * inv) % p_pow
                new_r = rem1 + mod1 * k
                new_roots.append((new_r % (mod1 * p_pow), mod1 * p_pow))

        all_roots = new_roots
        current_mod *= p_pow

    return sorted([r[0] for r in all_roots])

def _solve_prime_power(a: int, p: int, e: int) -> list[int]:
    n = p ** e
    a = a % n

    if p == 2:
        return _solve_mod_2pow(a, e)
    else:
        return _solve_mod_odd_prime_power(a, p, e)

def _solve_mod_2pow(a: int, e: int) -> list[int]:
    if e == 1:
        return [a % 2]

    if e == 2:
        if a % 4 == 0:
            return [0, 2]
        elif a % 4 == 1:
            return [1, 3]
        else:
            return []

    # e >=3
    if a % 2 != 0:
        if a % 8 != 1:
            return []
        x = 1
        for k in range(3, e):
            diff = (a - x * x) >> k
            t = diff & 1
            x += t << (k - 1)
        n = 1 << e
        r1 = x
        r2 = n - x
        r3 = (x + (1 << (e - 1))) % n
        r4 = (n - x + (1 << (e - 1))) % n
        return sorted({r1, r2, r3, r4})
    else:
        # a is even
        if a == 0:
            k = e
        else:
            k = 0
            temp = a
            while temp % 2 == 0:
                k += 1
                temp //= 2

        if k % 2 != 0:
            return []

        if k >= e:
            limit = 1 << ((e + 1) // 2)
            return list(range(0, 1 << e, limit))

        j = k // 2
        rem_e = e - k
        u = a >> k

        roots_y = _solve_mod_2pow(u, rem_e)
        if not roots_y:
            return []

        shift = 1 << j
        res = []
        for r in roots_y:
            x = (r * shift) % (1 << e)
            res.append(x)
            other = (x + (1 << (rem_e + j))) % (1 << e)
            res.append(other)
        return sorted(list(set(res)))

def _solve_mod_odd_prime_power(a: int, p: int, e: int) -> list[int]:
    n = p ** e

    if a % p == 0:
        k = 0
        temp = a
        while temp % p == 0:
            k += 1
            temp //= p

        if k % 2 != 0:
            return []

        half_k = k // 2
        rem_e = e - k

        if rem_e <= 0:
            limit = p ** ((e + 1) // 2)
            return list(range(0, p**e, limit))

        roots_y = _solve_mod_odd_prime_power(temp, p, rem_e)
        if not roots_y:
            return []

        shift = p ** half_k
        res = []
        for r in roots_y:
            x = (r * shift) % (p**e)
            res.append(x)
            other = (x + (p ** rem_e)) % (p**e)
            res.append(other)
        return sorted(list(set(res)))

    roots_p = tonelli_shanks(a, p)
    if not roots_p:
        return []

    all_roots = []
    for r in roots_p:
        roots_lifted = hensel_lift(r, a, p, e)
        all_roots.extend(roots_lifted)

    return sorted(all_roots)

def tonelli_shanks(n: int, p: int) -> list[int]:
    n = n % p
    if n == 0:
        return [0]
    if p == 2:
        return [n]

    if pow(n, (p - 1) // 2, p) != 1:
        return []

    Q = p - 1
    S = 0
    while Q % 2 == 0:
        Q //= 2
        S += 1

    z = 2
    while pow(z, (p - 1) // 2, p) != p - 1:
        z += 1

    M = S
    c = pow(z, Q, p)
    t = pow(n, Q, p)
    R = pow(n, (Q + 1) // 2, p)

    while True:
        if t == 1:
            return [R, p - R]

        i = 1
        temp = t
        while i < M:
            temp = pow(temp, 2, p)
            if temp == 1:
                break
            i += 1

        if i == M:
            return []

        b = pow(c, 1 << (M - i - 1), p)
        M = i
        c = pow(b, 2, p)
        t = (t * c) % p
        R = (R * b) % p

def hensel_lift(x0: int, a: int, p: int, e: int) -> list[int]:
    x = x0
    for k in range(1, e):
        num = (a - x * x) // (p ** k)
        inv_2x = pow((2 * x) % p, -1, p)
        t = (num * inv_2x) % p
        x += t * (p ** k)

    return [x % (p ** e)]

